/* ══════════════════════════════════════════════════════════════════
   POST DESIGN SYSTEM — Dynamic CSS post templates

   Templates define STRUCTURE (layout, text position, overlay type).
   AI generates VARIATIONS per run (colors, filter intensity, accent
   positions, gradient angles) so every post is unique but on-brand.
   ══════════════════════════════════════════════════════════════════ */

/* ── Dynamic style overrides generated by AI per run ── */
export interface StyleVariation {
  accentColor: string;        // hex, e.g. "#7ab82e"
  gradientAngle: number;      // 0-360
  filterContrast: number;     // 0.9-1.4
  filterSaturate: number;     // 0.8-1.5
  filterBrightness: number;   // 0.7-1.2
  filterSepia: number;        // 0-0.2
  overlayOpacity: number;     // 0.3-0.9
  headlineColor: string;      // hex
  sublineColor: string;       // hex with alpha
  vignetteStrength: number;   // 0-0.7
  accentWidth: number;        // 8-48 px
  borderRadius: number;       // 0-24 px for overlay shapes
}

export const DEFAULT_VARIATION: StyleVariation = {
  accentColor: "#7ab82e",
  gradientAngle: 180,
  filterContrast: 1.1,
  filterSaturate: 1.15,
  filterBrightness: 0.95,
  filterSepia: 0,
  overlayOpacity: 0.8,
  headlineColor: "#ffffff",
  sublineColor: "rgba(255,255,255,0.6)",
  vignetteStrength: 0.4,
  accentWidth: 40,
  borderRadius: 0,
};

/* ── Template structure ── */
export interface PostTemplate {
  id: string;
  name: string;
  category: "premium" | "bold" | "minimal" | "editorial" | "promo" | "engagement" | "storytelling" | "showcase";
  preview: string;
  layout: LayoutType;
}

export type LayoutType =
  | "bottom-gradient"    // gradient bottom, text in lower third
  | "center-hero"       // dark overlay, huge centered text
  | "top-headline"      // text at top, photo below
  | "side-panel"        // solid panel on left/right, photo on other side
  | "bottom-bar"        // solid bar at bottom
  | "frosted-center"    // frosted glass card centered
  | "diagonal-split"    // diagonal division
  | "frame-inset"       // thin border frame inset
  | "fullbleed-subtle"  // very subtle overlay, text at bottom
  | "top-bar"           // solid bar at top
  | "dual-tone"         // two-tone split background
  | "vignette-focus"    // heavy vignette, text in center
  | "banner-stripe"     // horizontal stripe across middle
  | "corner-card"       // small card in a corner
  | "floating-pill"     // pill-shaped text container floating
  | "magazine-grid"     // editorial grid lines
  | "gradient-sweep"    // angled gradient sweep across
  | "spotlight-circle"  // circular spotlight effect
  | "bottom-wave"       // wavy bottom overlay
  | "minimal-caption"   // barely any overlay, just tiny caption
  | "text-block"        // solid text block floating
  | "cinematic-bars"    // letterbox black bars top/bottom
  | "split-vertical";   // vertical 50/50 split

