export function getTemplateById(id: string): PostTemplate | undefined {
  return POST_TEMPLATES.find((t) => t.id === id);
}

export function getRandomVariation(baseAccent?: string): StyleVariation {
  const accents = ["#7ab82e", "#4d6340", "#3c4a30", "#795220", "#a07a40", "#8fd440", "#22c55e", "#059669", "#0ea5e9", "#e3e3d2"];
  const accent = baseAccent || accents[Math.floor(Math.random() * accents.length)];

  return {
    accentColor: accent,
    gradientAngle: 150 + Math.floor(Math.random() * 60),
    filterContrast: 1 + Math.random() * 0.3,
    filterSaturate: 0.9 + Math.random() * 0.5,
    filterBrightness: 0.8 + Math.random() * 0.3,
    filterSepia: Math.random() * 0.12,
    overlayOpacity: 0.5 + Math.random() * 0.35,
    headlineColor: "#ffffff",
    sublineColor: `rgba(255,255,255,${(0.5 + Math.random() * 0.3).toFixed(2)})`,
    vignetteStrength: 0.2 + Math.random() * 0.4,
    accentWidth: 20 + Math.floor(Math.random() * 28),
    borderRadius: Math.floor(Math.random() * 20),
  };
}
